const c=1000000000000n,t=r=>{if(!/^\d+(\.\d{0,12})?$/.test(String(r)))throw new Error("Invalid decimal");const[n,i=""]=String(r).split(".");return BigInt(n)*c+BigInt(i.padEnd(12,"0"))},s=(r,n)=>(r+n-1n)/n;function l(r,n,i="1"){try{const u=t(r);if(u<=0n||t(i)<=0n)return null;const o=u*(c+t(n.markup_percent)/100n)/c,a=u+t(n.minimum_profit),d=s(o>a?o:a,t(n.rounding))*t(n.rounding),e=s(d*t(i)/c,c/100n);return`${e/100n}.${String(e%100n).padStart(2,"0")}`}catch{return null}}function m(r,n){try{const i=t(r);if(i<=0n)return null;const o=(t(n)*c/i+500000n)/1000000n;return`${o/1000000n}.${String(o%1000000n).padStart(6,"0")}`}catch{return null}}export{l as a,m as p};
